create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null check (length(btrim(full_name)) between 2 and 120), created_at timestamptz not null default now());
create table public.dentists (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, specialty text not null, district text not null, consultation_price numeric(10,2) not null check (consultation_price >= 0), currency text not null default 'PEN' check(currency = 'PEN'), initials text not null, avatar_color text not null, description text not null, is_demo boolean not null default true check(is_demo), is_active boolean not null default true, created_at timestamptz not null default now());
create index dentists_district_specialty_idx on public.dentists(district, specialty);
create table public.appointment_requests (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, dentist_id uuid not null references public.dentists(id), contact_name text not null check(length(btrim(contact_name)) between 2 and 120), contact_email text not null check(length(contact_email) <= 254 and contact_email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'), preferred_date date not null, preferred_time time, message text not null default '' check(length(message) <= 1000), status text not null default 'requested' check(status in ('requested','cancelled')), is_demo boolean not null default true check(is_demo), created_at timestamptz not null default now());
create index appointment_requests_user_idx on public.appointment_requests(user_id, created_at desc);
create index appointment_requests_dentist_idx on public.appointment_requests(dentist_id);
create table public.patient_consents (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, policy_version text not null check(length(btrim(policy_version)) between 1 and 80), consent_text text not null check(length(btrim(consent_text)) between 20 and 5000), purpose text not null default 'academic_photo_storage' check(purpose = 'academic_photo_storage'), accepted_at timestamptz not null default now(), revoked_at timestamptz check(revoked_at is null or revoked_at >= accepted_at), unique(user_id,id));
create index patient_consents_user_idx on public.patient_consents(user_id);
create table public.dental_photos (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, consent_id uuid not null, bucket_id text not null default 'dental-photos' check(bucket_id = 'dental-photos'), object_path text not null unique, original_filename text not null check(length(original_filename) between 1 and 255), mime_type text not null check(mime_type in ('image/jpeg','image/png','image/webp')), size_bytes bigint not null check(size_bytes between 1 and 8388608), created_at timestamptz not null default now(), foreign key(user_id,consent_id) references public.patient_consents(user_id,id), check (object_path like user_id::text || '/' || consent_id::text || '/%' and length(split_part(object_path,'/',3)) > 0));
create index dental_photos_user_consent_idx on public.dental_photos(user_id,consent_id);
comment on table public.appointment_requests is 'Solicitudes académicas: no confirman reservas ni contactan odontólogos reales.';
comment on table public.patient_consents is 'Consentimiento explícito para almacenamiento académico; no autoriza IA ni entrenamiento.';
comment on table public.dental_photos is 'Metadatos de archivos privados. Borrar un registro no elimina el archivo: usar Storage API para borrarlo.';
alter table public.profiles enable row level security; alter table public.dentists enable row level security; alter table public.appointment_requests enable row level security; alter table public.patient_consents enable row level security; alter table public.dental_photos enable row level security;
revoke all on public.profiles, public.dentists, public.appointment_requests, public.patient_consents, public.dental_photos from anon, authenticated;
grant usage on schema public to anon, authenticated; grant select on public.dentists to anon, authenticated; grant select, insert on public.profiles to authenticated; grant update(full_name) on public.profiles to authenticated; grant select, insert on public.appointment_requests to authenticated; grant update(status) on public.appointment_requests to authenticated; grant select, insert on public.patient_consents to authenticated; grant update(revoked_at) on public.patient_consents to authenticated; grant select, insert, delete on public.dental_photos to authenticated;
create policy profiles_read on public.profiles for select to authenticated using(id = (select auth.uid()));
create policy profiles_create on public.profiles for insert to authenticated with check(id = (select auth.uid()));
create policy profiles_update on public.profiles for update to authenticated using(id = (select auth.uid())) with check(id = (select auth.uid()));
create policy dentists_read on public.dentists for select to anon, authenticated using(is_active);
create policy requests_read on public.appointment_requests for select to authenticated using(user_id = (select auth.uid()));
create policy requests_create on public.appointment_requests for insert to authenticated with check(user_id = (select auth.uid()) and status = 'requested' and preferred_date >= current_date and exists(select 1 from public.dentists d where d.id = dentist_id and d.is_active));
create policy requests_cancel on public.appointment_requests for update to authenticated using(user_id = (select auth.uid())) with check(user_id = (select auth.uid()) and status = 'cancelled');
create policy consents_read on public.patient_consents for select to authenticated using(user_id = (select auth.uid()));
create policy consents_create on public.patient_consents for insert to authenticated with check(user_id = (select auth.uid()) and revoked_at is null);
create policy consents_revoke on public.patient_consents for update to authenticated using(user_id = (select auth.uid())) with check(user_id = (select auth.uid()) and revoked_at is not null);
create policy photos_read on public.dental_photos for select to authenticated using(user_id = (select auth.uid()));
create policy photos_create on public.dental_photos for insert to authenticated with check(user_id = (select auth.uid()) and exists(select 1 from public.patient_consents c where c.id = consent_id and c.user_id = (select auth.uid()) and c.revoked_at is null));
create policy photos_delete on public.dental_photos for delete to authenticated using(user_id = (select auth.uid()));
