create policy dentaia_photo_upload on storage.objects for insert to authenticated with check(bucket_id = 'dental-photos' and (storage.foldername(name))[1] = (select auth.uid())::text and exists(select 1 from public.patient_consents c where c.user_id = (select auth.uid()) and c.id::text = (storage.foldername(name))[2] and c.revoked_at is null));
create policy dentaia_photo_read on storage.objects for select to authenticated using(bucket_id = 'dental-photos' and (storage.foldername(name))[1] = (select auth.uid())::text and exists(select 1 from public.patient_consents c where c.user_id = (select auth.uid()) and c.id::text = (storage.foldername(name))[2] and c.revoked_at is null));
create policy dentaia_photo_delete on storage.objects for delete to authenticated using(bucket_id = 'dental-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
